import {serviceSummary, branchLocations} from '/overview.js';
import {renderBranchMap} from '/branch-map.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const COMPANY='PowerVision Systems Pvt Ltd';
const icons={
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',
 overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 visits:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16m-12 4h3m3 0h2"/>',
 reports:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9Z"/><path d="M14 3v6h6M8 13h8m-8 4h6"/>',
 assets:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5m-18 5 9 5 9-5"/>',
 inventory:'<path d="m12 3 9 5v10l-9 5-9-5V8l9-5Zm-9 5 9 5 9-5m-9 5v10M7.5 5.5l9 5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 receive:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 payments:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18m-6 6h3"/>',
 audit:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 11-2l3 7M4 12l3 7a7 7 0 0 0 11-2"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',
 print:'<path d="M7 8V3h10v5M7 17H4V9h16v8h-3M7 14h10v7H7Z"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 person:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'
};
const icon=(name,className='')=>`<svg class="icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]??icons.reports}</svg>`;
let user,visits=[],assets=[],fields=[],users=[],tab='overview',search='',region='',warranty='',status='',month=new Date().toISOString().slice(0,7);
let mapConfiguration={},lastUpdated=null,refreshVersion=0,refreshing=false,selectedMapBranch=null,detailVersion=0;
let inventoryData=null,inventoryLoading=false,inventoryError='',inventorySearch='',inventoryCategory='',inventoryItem='',inventoryType='',inventoryVersion=0,inventoryUpdatedAt=null;
const money=value=>'PKR '+Number(value).toLocaleString('en-PK');
const dateTime=value=>value?new Date(value).toLocaleString('en-PK',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Karachi'}):'Not recorded';
const statusLabels={scheduled:'Scheduled',submitted:'Awaiting review',acknowledged:'Acknowledged',unacknowledged:'Needs correction',Warranty:'Warranty',OOW:'AMC · Out of warranty'};
const badge=value=>`<span class="badge ${esc(value)}">${esc(statusLabels[value]??String(value??'').replaceAll('_',' '))}</span>`;
const eligible=visit=>visit.status==='acknowledged'&&visit.warranty==='OOW';
const companyStockAccess=()=>['ho','vendor'].includes(user?.role);
const quantity=value=>Number(value).toLocaleString('en-PK',{maximumFractionDigits:6});
const filtered=()=>visits.filter(visit=>visit.month===month&&(!region||visit.region===region)&&(!warranty||visit.warranty===warranty)&&(!status||visit.status===status)&&(!search||JSON.stringify([visit.id,visit.assetId,visit.branchName,visit.branchCode,visit.vendor,visit.fsr?.fsrNumber,assets.find(asset=>asset.id===visit.assetId)?.engineSerial]).toLowerCase().includes(search.toLowerCase())));
const workspace=()=>user.role==='client_ho'?{name:'UBL Head Office',description:'Client workspace',scope:'Your UBL service records'}:user.role==='branch'?{name:'UBL Branch',description:'Client workspace',scope:`Branch ${user.branchCode} service records`}:user.role==='technician'?{name:'Field Technician',description:'Technician workspace',scope:'Your assigned service visits'}:{name:'PowerVision',description:'Company workspace',scope:'Assigned UBL service operations'};
async function api(path,body){const response=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const result=await response.json();if(!response.ok)throw new Error(result.error||'The request could not be completed.');return result;}
function notify(message){$('#notice').textContent=message;$('#notice').classList.add('show');setTimeout(()=>$('#notice').classList.remove('show'),6000);}
async function refresh({background=false}={}){
 const version=++refreshVersion;refreshing=true;
 try{const result=await Promise.all([api('visits?summary=1'),api('assets'),api('fields')]);if(version!==refreshVersion)return;[visits,assets,fields]=result;lastUpdated=new Date();
  if(background&&($('#detail').open||document.activeElement?.matches('input,select,textarea')||tab!=='overview'))return;
  const scroll=window.scrollY;render();if(background)window.scrollTo(0,scroll);
 }finally{if(version===refreshVersion)refreshing=false;}
}

function overview(rows){
 const summary=serviceSummary(rows),branches=branchLocations(rows,assets),missing=branches.filter(branch=>branch.latitude===null||branch.longitude===null).length;
 const cards=[['amc','AMC gensets','Out of warranty service','bolt'],['warranty','Warranty gensets','Covered visits · zero visit charge','shield'],['total','Total gensets','AMC + warranty in selected period','assets']];
 return `<div class="dashboard-topline"><div><span class="live-dot"></span>Live service progress <span class="updated-at">Checked ${lastUpdated?lastUpdated.toLocaleTimeString('en-PK',{timeZone:'Asia/Karachi'}):'—'} · refreshes every 15s</span></div><button id="refresh-data" class="text-button">${icon('refresh')}Refresh now</button></div>
 <div class="operations-grid"><article class="panel branch-map-panel"><div class="panel-heading"><div><span class="eyebrow">BRANCH NETWORK</span><h2>Assigned UBL branches</h2></div><span class="branch-count">${icon('pin')}${branches.length} locations</span></div><div class="map-stage"><div id="branch-map" aria-label="Assigned UBL branch locations"><div class="map-empty">Loading branch locations…</div></div><span class="map-provider" id="map-provider">Loading map…</span></div><div class="map-legend"><span><i class="map-dot performed"></i>FSR submitted</span><span><i class="map-dot remaining"></i>Remaining</span></div><div id="map-selection" class="map-selection" aria-live="polite">${icon('pin')}<span>Select a location to see its service progress.</span></div>
 ${branches.some(branch=>branch.locationSource==='Demo city location')?'<p class="map-disclaimer">Pins use demo city coordinates; real UBL branch locations have not been verified.</p>':''}
 ${missing?`<p class="map-disclaimer">${missing} branches have no coordinates. They count toward totals but have no map pin.</p>`:''}
 <div class="branch-picker" aria-label="Assigned branches">${branches.map((branch,index)=>`<button class="branch-chip ${branch.state}" data-branch="${esc(branch.branchCode)}"><span class="branch-index">${index+1}</span><span>${esc(branch.name)}<small>${esc(branch.branchCode)} · ${branch.performed}/${branch.total} performed${branch.latitude===null?' · No location':''}</small></span>${icon('arrow')}</button>`).join('')||'<div class="empty">No branches match the selected filters.</div>'}</div></article>
 <section class="service-overview" aria-label="AMC warranty and total service overview"><div class="overview-heading"><span class="eyebrow">SERVICE DELIVERY</span><h2>Monthly progress</h2><p>Updated from technician FSR submissions.</p></div>${cards.map(([key,title,note,symbol])=>{
  const count=summary[key],percent=count.total?Math.round(count.performed/count.total*100):0;
  return `<article class="service-card ${key}" data-summary="${key}"><div class="service-card-heading"><span class="service-symbol">${icon(symbol)}</span><div><h3>${title}</h3><p>${note}</p></div><span class="completion-percentage">${percent}%</span></div><div class="service-counts"><div><span>Total</span><strong data-count="total">${count.total}</strong></div><div class="performed-count"><span>Performed</span><strong data-count="performed">${count.performed}</strong></div><div class="remaining-count"><span>Remaining</span><strong data-count="remaining">${count.remaining}</strong></div></div><progress class="service-progress" value="${count.performed}" max="${count.total||1}" aria-label="${title} performed"></progress><div class="card-review-status"><span>${count.awaitingReview} awaiting review</span><span>${count.acknowledged} acknowledged</span>${count.needsCorrection?`<span class="danger">${count.needsCorrection} need correction</span>`:''}</div></article>`;
 }).join('')}<p class="overview-explanation">Performed means an FSR has been submitted. Client acknowledgement and payment eligibility are tracked separately.</p></section></div>
 <div class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">VISIT REGISTER</span><h2>Visit activity</h2></div><button class="text-button" id="view-all">View all visits ${icon('arrow')}</button></div>${table(rows.slice(0,8))}</div>`;
}
function mountMap(rows){
 const branches=branchLocations(rows,assets),element=$('#branch-map');if(!element)return;
 const select=branch=>{if(!element.isConnected||!branch)return;selectedMapBranch=branch.branchCode;
  $('#map-selection').innerHTML=`<div><b>${esc(branch.name)} · ${esc(branch.branchCode)}</b><span>${branch.total} total · ${branch.performed} performed · ${branch.remaining} remaining</span></div><button id="branch-visits" class="text-button">View visits ${icon('arrow')}</button>`;
  element.closest('.panel').querySelectorAll('[data-branch]').forEach(button=>button.classList.toggle('selected',button.dataset.branch===branch.branchCode));
  $('#branch-visits').onclick=()=>{search=branch.branchCode;tab='visits';render();};
 };
 document.querySelectorAll('[data-branch]').forEach(button=>button.onclick=()=>select(branches.find(branch=>branch.branchCode===button.dataset.branch)));
 const previouslySelected=branches.find(branch=>branch.branchCode===selectedMapBranch);if(previouslySelected)select(previouslySelected);
 renderBranchMap(element,branches,mapConfiguration,select,mode=>{if(element.isConnected)$('#map-provider').textContent=mode;}).catch(()=>{if(element.isConnected){element.innerHTML='<div class="map-empty">The map could not load. Branch progress is available below.</div>';$('#map-provider').textContent='Map unavailable';}});
}
function reports(rows){
 const submitted=rows.filter(visit=>visit.fsr),pending=submitted.filter(visit=>visit.status==='submitted').length,acknowledged=submitted.filter(visit=>visit.status==='acknowledged').length;
 return `<div class="report-sharing"><div class="sharing-mark">${icon('reports')}</div><div><h2>One complete service record</h2><p>Technician readings, job details and evidence are available to authorized UBL and PowerVision users.</p></div><span class="sharing-client">PowerVision <span>↔</span> UBL</span></div>
 <div class="stats report-stats"><article><span>Submitted reports</span><strong>${submitted.length}</strong><small>All submitted FSRs in these filters</small></article><article><span>Awaiting client review</span><strong>${pending}</strong><small>Submitted to the assigned branch</small></article><article><span>Acknowledged</span><strong>${acknowledged}</strong><small>Client confirmation recorded</small></article></div>
 <div class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">FIELD SERVICE REPORTS</span><h2>Detailed FSR records</h2></div><small>${submitted.length} reports · selected period</small></div><div class="table-scroll"><table><thead><tr><th>FSR / Branch</th><th>Genset</th><th>Submitted · PKT</th><th>Client decision</th><th></th></tr></thead><tbody>${submitted.length?submitted.map(visit=>`<tr><td><b class="fsr-id">${esc(visit.fsr.fsrNumber)}</b><small>${esc(visit.branchName)} · ${esc(visit.branchCode)}</small></td><td>${esc(visit.assetId)}<small>${esc(visit.region)}</small></td><td>${esc(dateTime(visit.fsr.submittedAt))}</td><td>${badge(visit.status)}</td><td><button class="text-button" data-visit="${esc(visit.id)}">Full report ${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty"><div class="empty-icon">'+icon('reports')+'</div><b>No FSRs submitted for these filters</b><p>Reports appear here when a technician submits a visit.</p></td></tr>'}</tbody></table></div></div>`;
}
const stockStatus=item=>!item.active&&item.active!==undefined?['inactive','Inactive']:Number(item.quantity)<=0?['empty-stock','Out of stock']:Number(item.quantity)<=Number(item.reorderLevel)?['low-stock','Low stock']:['stock-available','Available'];
const movementLabels={opening:'Opening stock',receipt:'Stock received',fsr_usage:'FSR usage',fsr_correction:'FSR correction'};
function inventoryPage(){
 if(!inventoryData)return `<div class="panel inventory-loading" role="status">${icon('inventory')}<h2>${inventoryError?'Inventory could not load':'Loading your stock records…'}</h2>${inventoryError?`<p>${esc(inventoryError)}</p><button id="retry-inventory" class="button">Try again</button>`:'<p>Opening the PowerVision parts and materials catalogue.</p>'}</div>`;
 const {items,movements}=inventoryData,active=items.filter(item=>item.active!==false),lowStock=active.filter(item=>Number(item.quantity)<=Number(item.reorderLevel)),empty=active.filter(item=>Number(item.quantity)<=0).length;
 const catalogue=items.filter(item=>(!inventoryCategory||item.category===inventoryCategory)&&(!inventorySearch||[item.name,item.sku,item.category].join(' ').toLowerCase().includes(inventorySearch.toLowerCase())));
 const ledger=movements.filter(movement=>(!inventoryItem||movement.itemId===inventoryItem)&&(!inventoryType||movement.type===inventoryType));
 const categories=[...new Set(items.map(item=>item.category).filter(Boolean))].sort();
 return `<div class="inventory-toolbar"><div><span class="live-dot"></span>PowerVision stock register <span class="inventory-updated">${inventoryUpdatedAt?'Checked '+esc(dateTime(inventoryUpdatedAt)):''}</span></div><div><button id="refresh-inventory" class="text-button" ${inventoryLoading?'disabled':''}>${icon('refresh')}${inventoryLoading?'Refreshing…':'Refresh stock'}</button><button id="receive-stock" class="button inventory-receive" ${active.length?'':'disabled'}>${icon('receive')}Receive stock</button><button id="add-stock-item" class="button">${icon('plus')}Add item</button></div></div>
 ${inventoryError?`<div class="inventory-error" role="alert">${esc(inventoryError)}</div>`:''}
 <div class="stats inventory-stats"><article><span>Catalogue SKUs</span><strong>${active.length}</strong><small>Active parts and materials</small></article><article class="inventory-low-stat"><span>Needs restocking</span><strong>${lowStock.length}</strong><small>${empty} out of stock · at or below reorder level</small></article><article><span>Stock receipts</span><strong>${movements.filter(movement=>movement.type==='receipt').length}</strong><small>Recorded receipt entries</small></article><article><span>FSR usage entries</span><strong>${movements.filter(movement=>movement.type==='fsr_usage').length}</strong><small>Material deductions linked to submitted visits</small></article></div>
 <div class="inventory-guidance">${icon('inventory')}<div><b>Stock follows the technician’s FSR</b><p>Tracked materials are deducted when the FSR is submitted. A client correction request keeps the recorded usage; a corrected submission adjusts the difference.</p></div></div>
 <section class="panel table-panel inventory-catalogue"><div class="panel-heading"><div><span class="eyebrow">PARTS & MATERIALS</span><h2>Stock catalogue</h2></div><small>${catalogue.length} of ${items.length} items</small></div><div class="inventory-filters"><label class="inventory-search-label">Find an item<div class="search-control">${icon('search')}<input id="inventory-search" type="search" placeholder="Item name, SKU or category" value="${esc(inventorySearch)}"></div></label><label>Category<select id="inventory-category"><option value="">All categories</option>${categories.map(category=>`<option value="${esc(category)}" ${inventoryCategory===category?'selected':''}>${esc(category)}</option>`).join('')}</select></label>${inventorySearch||inventoryCategory?'<button id="reset-inventory-search" class="text-button">Reset search</button>':''}</div>
 <div class="table-scroll"><table><thead><tr><th>Item / SKU</th><th>Category</th><th>On hand</th><th>Reorder level</th><th>Stock status</th><th></th></tr></thead><tbody>${catalogue.length?catalogue.map(item=>{const [code,label]=stockStatus(item);return `<tr><td><b>${esc(item.name)}</b><small>${esc(item.sku)}</small></td><td>${esc(item.category||'—')}</td><td><b class="stock-quantity">${quantity(item.quantity)}</b> <span class="stock-unit">${esc(item.unit)}</span></td><td>${quantity(item.reorderLevel)} <span class="stock-unit">${esc(item.unit)}</span></td><td><span class="badge ${code}">${label}</span></td><td><button class="text-button" data-receive-item="${esc(item.id)}" ${item.active===false?'disabled':''}>Receive ${icon('plus')}</button></td></tr>`;}).join(''):`<tr><td colspan="6" class="empty"><div class="empty-icon">${icon('inventory')}</div><b>${items.length?'No items match the search':'Your stock catalogue is empty'}</b><p>${items.length?'Try another SKU, name or category.':'Add your first part or material with its opening quantity.'}</p></td></tr>`}</tbody></table></div></section>
 <section class="panel table-panel inventory-ledger"><div class="panel-heading"><div><span class="eyebrow">STOCK TRACEABILITY</span><h2>Receipts & FSR usage</h2></div><small>${ledger.length} of ${movements.length} movements</small></div><div class="inventory-filters ledger-filters"><label>Item<select id="inventory-ledger-item"><option value="">All items</option>${items.map(item=>`<option value="${esc(item.id)}" ${inventoryItem===item.id?'selected':''}>${esc(item.sku)} · ${esc(item.name)}</option>`).join('')}</select></label><label>Movement type<select id="inventory-ledger-type"><option value="">All movements</option>${Object.entries(movementLabels).map(([type,label])=>`<option value="${type}" ${inventoryType===type?'selected':''}>${label}</option>`).join('')}</select></label>${inventoryItem||inventoryType?'<button id="reset-inventory-ledger" class="text-button">Reset filters</button>':''}</div><p class="table-note">Each movement keeps its own unit. Positive quantities add stock; negative quantities use stock.</p>
 <div class="table-scroll"><table><thead><tr><th>Date · PKT / Type</th><th>Item</th><th>Stock change</th><th>Recorded by</th><th>Branch / Client</th><th>FSR / Reference</th></tr></thead><tbody>${ledger.length?ledger.map(movement=>`<tr><td>${esc(dateTime(movement.at))}<small>${esc(movementLabels[movement.type]??movement.type)}</small></td><td><b>${esc(movement.itemName??movement.name??movement.sku)}</b><small>${esc(movement.sku)}</small></td><td><b class="stock-change ${Number(movement.quantity)>0?'stock-added':Number(movement.quantity)<0?'stock-used':''}">${Number(movement.quantity)>0?'+':''}${quantity(movement.quantity)} ${esc(movement.unit)}</b></td><td>${esc(movement.actor?.name??movement.actor?.id??'Not recorded')}<small>${esc(movement.actor?.employeeId??'')}</small></td><td>${esc(movement.branchName??'—')}<small>${esc([movement.branchCode,movement.client].filter(Boolean).join(' · '))}</small></td><td>${movement.visitId?`<button class="text-button ledger-fsr-link" data-visit="${esc(movement.visitId)}">${esc(movement.fsrNumber??movement.reference??movement.visitId)} ${icon('external')}</button>`:`<b>${esc(movement.reference||'—')}</b>`}${movement.revision?`<small>FSR revision ${esc(movement.revision)}</small>`:''}${movement.note?`<small class="ledger-note">${esc(movement.note)}</small>`:''}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No stock movements match these filters.</td></tr>'}</tbody></table></div></section>`;
}
function renderInventory(){
 if(tab!=='inventory'||!companyStockAccess())return;
 $('#page').innerHTML=inventoryPage();
 $('#retry-inventory')?.addEventListener('click',loadInventory);
 $('#refresh-inventory')?.addEventListener('click',loadInventory);
 $('#add-stock-item')?.addEventListener('click',()=>inventoryDialog('item'));
 $('#receive-stock')?.addEventListener('click',()=>inventoryDialog('receipt'));
 document.querySelectorAll('[data-receive-item]').forEach(button=>button.onclick=()=>inventoryDialog('receipt',button.dataset.receiveItem));
 $('#inventory-search')?.addEventListener('change',event=>{inventorySearch=event.target.value;renderInventory();});
 $('#inventory-category')?.addEventListener('change',event=>{inventoryCategory=event.target.value;renderInventory();});
 $('#inventory-ledger-item')?.addEventListener('change',event=>{inventoryItem=event.target.value;renderInventory();});
 $('#inventory-ledger-type')?.addEventListener('change',event=>{inventoryType=event.target.value;renderInventory();});
 $('#reset-inventory-search')?.addEventListener('click',()=>{inventorySearch='';inventoryCategory='';renderInventory();});
 $('#reset-inventory-ledger')?.addEventListener('click',()=>{inventoryItem='';inventoryType='';renderInventory();});
 document.querySelectorAll('[data-visit]').forEach(button=>button.onclick=()=>detail(button.dataset.visit));
}
async function loadInventory(){
 if(!companyStockAccess())return;
 const version=++inventoryVersion,account=user.id;inventoryLoading=true;inventoryError='';renderInventory();
 try{const result=await api('inventory');if(version!==inventoryVersion||account!==user.id)return;inventoryData=result;inventoryUpdatedAt=new Date().toISOString();}
 catch(error){if(version===inventoryVersion&&account===user.id)inventoryError=error.message;}
 finally{if(version===inventoryVersion&&account===user.id){inventoryLoading=false;renderInventory();}}
}
function inventoryDialog(mode,itemId=''){
 if(!companyStockAccess())return;
 const dialog=$('#inventory-detail'),receipt=mode==='receipt',items=(inventoryData?.items??[]).filter(item=>item.active!==false),item=items.find(item=>item.id===itemId)??items[0];
 if(receipt&&!items.length){notify('Add a stock item before recording a receipt.');return;}
 dialog.className='inventory-dialog';
 dialog.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">POWERVISION STOCK REGISTER</span><h2>${receipt?'Receive stock':'Add a stock item'}</h2></div><button class="close-button" id="close-inventory" aria-label="Close inventory form">${icon('close')}</button></div><p class="inventory-form-intro">${receipt?'Record incoming parts or materials against an existing catalogue item.':'Create a part or material and record the stock already available.'}</p><form id="inventory-form">${receipt?`<label>Stock item<select name="itemId" id="receipt-item" required>${items.map(stock=>`<option value="${esc(stock.id)}" ${stock.id===item?.id?'selected':''}>${esc(stock.sku)} · ${esc(stock.name)}</option>`).join('')}</select></label><div id="receipt-stock-context" class="receipt-stock-context"></div><div class="form-grid"><label>Quantity received<input name="quantity" type="number" min="0.001" step="0.001" required placeholder="Enter received quantity"></label><label>Receipt / purchase reference<input name="reference" maxlength="160" placeholder="Invoice or delivery reference" required></label></div><label class="inventory-note-label">Receipt notes<textarea name="note" maxlength="2000" placeholder="Supplier, delivery details or other notes"></textarea></label>`:`<div class="form-grid"><label>SKU / item code<input name="sku" maxlength="64" required placeholder="e.g. OIL-FILTER-001"></label><label>Item name<input name="name" maxlength="160" required placeholder="e.g. Oil filter"></label><label>Category<input name="category" maxlength="80" list="inventory-categories" required placeholder="e.g. Filters"><datalist id="inventory-categories">${[...new Set((inventoryData?.items??[]).map(stock=>stock.category))].filter(Boolean).map(category=>`<option value="${esc(category)}"></option>`).join('')}</datalist></label><label>Unit<select name="unit" required><option value="pcs">Pieces (pcs)</option><option value="litre">Litres</option><option value="kg">Kilograms (kg)</option><option value="metre">Metres</option><option value="set">Sets</option></select></label><label>Opening quantity<input name="openingQuantity" type="number" min="0" step="0.001" value="0" required></label><label>Reorder level<input name="reorderLevel" type="number" min="0" step="0.001" value="0" required></label></div><p class="inventory-form-help">The item is flagged for restocking when its balance reaches the reorder level. Keep the selected unit consistent with technician usage.</p>`}<p id="inventory-form-error" class="danger" role="alert"></p><div class="inventory-form-actions"><button type="button" id="cancel-inventory" class="text-button">Cancel</button><button class="button" type="submit">${icon(receipt?'receive':'plus')}${receipt?'Record stock receipt':'Create stock item'}</button></div></form>`;
 const context=()=>{const selected=items.find(stock=>stock.id===$('#receipt-item')?.value);if(selected)$('#receipt-stock-context').innerHTML=`<span>Current balance <b>${quantity(selected.quantity)} ${esc(selected.unit)}</b></span><small>Enter the received quantity in ${esc(selected.unit)}.</small>`;};
 if(receipt){context();$('#receipt-item').onchange=context;}
 if(!dialog.open)dialog.showModal();$('#inventory-form input')?.focus();$('#close-inventory').onclick=$('#cancel-inventory').onclick=()=>dialog.close();
 $('#inventory-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,account=user.id;button.disabled=true;$('#inventory-form-error').textContent='';try{const values=Object.fromEntries(new FormData(event.target));for(const key of receipt?['quantity']:['openingQuantity','reorderLevel'])values[key]=Number(values[key]);await api(receipt?'inventory/receipts':'inventory/items',values);if(user.id!==account)return;dialog.close();await loadInventory();notify(receipt?'Stock receipt recorded. The item balance has been updated.':'Stock item created with its opening quantity.');}catch(error){$('#inventory-form-error').textContent=error.message;}finally{button.disabled=false;}};
}
function render(){
 const rows=filtered(),context=workspace(),payable=rows.filter(eligible).reduce((total,visit)=>total+visit.rate,0);
 const headings={overview:['Operations overview','Track your branch network and monthly service progress.'],visits:['Service visits','Follow assigned visits from scheduling to client acknowledgement.'],reports:['Field service reports','Review complete technician records, evidence and revision history.'],assets:['Genset asset register','Find the equipment linked to your authorized service visits.'],inventory:['Inventory management','Track PowerVision parts, stock receipts and technician material usage.'],payments:['Payment reconciliation','Review branch-acknowledged AMC visits and the monthly statement.'],audit:['Audit history','Trace recorded service submissions and client decisions.']};
 const navigation=[['overview','Overview'],['visits','Service visits'],['reports','FSR reports'],['assets','Asset register'],['inventory','Inventory'],['payments','Reconciliation'],['audit','Audit history']].filter(([id])=>!['payments','inventory'].includes(id)||companyStockAccess());
 if(!navigation.some(([id])=>id===tab))tab='overview';
 $('#app').innerHTML=`<aside><a class="brand" href="/" aria-label="PowerVision Systems Pvt Ltd home"><span class="brand-icon">${icon('bolt')}</span><div>POWER<span class="brand-vision">VISION</span><small>SYSTEMS PVT LTD</small></div></a><div class="workspace-card"><span class="workspace-avatar">${icon(context.description==='Client workspace'?'shield':'assets')}</span><div><strong>${esc(context.name)}</strong><small>${esc(context.description)}</small></div><span class="workspace-dot"></span></div><div class="workspace-label">WORKSPACE</div><nav aria-label="Main navigation">${navigation.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='reports'?`<small>${visits.filter(visit=>visit.fsr).length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="field-app-card">${icon('person')}<strong>Field technician app</strong><p>Complete visits and submit FSRs.</p><a class="technician-app-link" href="/technician/" target="_blank" rel="noopener">Open mobile workspace ${icon('external')}</a></div><span class="live-dot"></span>Local development demo<small>Synthetic records · limited access</small></div></aside>
 <main><header><div class="breadcrumb">${esc(COMPANY)}<span>/ ${esc(headings[tab][0])}</span></div><label class="account"><span class="account-avatar">${icon('person')}</span><span><small>DEMO ACCOUNT</small><select id="user" aria-label="Select demo account">${users.map(account=>`<option value="${esc(account.id)}" ${account.id===user.id?'selected':''}>${esc(account.name)}</option>`).join('')}</select></span></label></header>
 <section class="content"><div class="page-heading"><div><div class="eyebrow">${tab==='inventory'?'POWERVISION COMPANY STOCK':esc(context.scope.toUpperCase())}</div><h1>${headings[tab][0]}</h1><p>${headings[tab][1]}</p></div><div class="client-pill">${tab==='inventory'?`<span>STOCK</span>${icon('inventory')}`:'<span>CLIENT</span><strong>UBL</strong>'}</div></div><div class="demo-banner"><span class="demo-label">DEMO</span><span>${tab==='inventory'?'Development stock register. Demo catalogue entries are synthetic.':'Synthetic service records and locations. Real UBL branch data has not been imported.'}</span></div>
 ${tab==='inventory'?'':`<div class="filters" aria-label="Filter service records"><label>Period<input id="month" type="month" value="${esc(month)}"></label><label class="search-label">Search<div class="search-control">${icon('search')}<input id="search" placeholder="Branch, asset, serial or FSR" value="${esc(search)}"></div></label><label>Region<select id="region"><option value="">All regions</option>${['South','Central','North'].map(value=>`<option ${value===region?'selected':''}>${value}</option>`).join('')}</select></label><label>Coverage<select id="warranty"><option value="">All gensets</option>${['Warranty','OOW'].map(value=>`<option value="${value}" ${value===warranty?'selected':''}>${value==='OOW'?'AMC · Out of warranty':'Warranty'}</option>`).join('')}</select></label><label>Visit status<select id="status"><option value="">All statuses</option>${['scheduled','submitted','acknowledged','unacknowledged'].map(value=>`<option value="${value}" ${value===status?'selected':''}>${statusLabels[value]}</option>`).join('')}</select></label>${search||region||warranty||status?'<button id="clear-filters" class="text-button filter-reset">Reset</button>':''}</div>`}
 <div id="page"></div><footer>${esc(COMPANY)} <span>·</span> Digital service records <span>·</span> Times shown in Pakistan Standard Time</footer></section></main>`;
 if(window.matchMedia('(max-width:780px)').matches){const navigationElement=$('nav'),activeButton=navigationElement.querySelector('[aria-current="page"]');navigationElement.scrollLeft=Math.max(0,activeButton.offsetLeft-navigationElement.offsetLeft-(navigationElement.clientWidth-activeButton.offsetWidth)/2);}
 if(tab==='overview'){$('#page').innerHTML=overview(rows);mountMap(rows);}
 if(tab==='visits')$('#page').innerHTML=`<div class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">ASSIGNED SERVICE</span><h2>Visit register</h2></div><small>${rows.length} visits · selected period</small></div>${table(rows)}</div>`;
 if(tab==='reports')$('#page').innerHTML=reports(rows);
 if(tab==='inventory')renderInventory();
 if(tab==='assets')$('#page').innerHTML=`<div class="panel table-panel"><div class="panel-heading"><h2>Genset register</h2><small>Assets with matching visits</small></div><div class="table-scroll"><table><thead><tr><th>Genset</th><th>Branch</th><th>Region</th><th>Serial number</th><th>Rating</th><th>Coverage</th></tr></thead><tbody>${assets.filter(asset=>rows.some(visit=>visit.assetId===asset.id)).map(asset=>`<tr><td><b>${esc(asset.id)}</b><small>${esc(asset.model)}</small></td><td>${esc(asset.branchName)}<small>${esc(asset.branchCode)}</small></td><td>${esc(asset.region)}</td><td>${esc(asset.engineSerial)}</td><td>${esc(asset.rating)} kVA</td><td>${badge(asset.warranty)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No assets match these filters.</td></tr>'}</tbody></table></div></div>`;
 if(tab==='payments')$('#page').innerHTML=`<div class="stats payment-stats"><article><span>Eligible visits</span><strong>${rows.filter(eligible).length}</strong><small>Branch-acknowledged AMC visits only</small></article><article><span>Total payable</span><strong>${money(payable)}</strong><small>Warranty visits: PKR 0</small></article></div><div class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">RECONCILIATION</span><h2>Monthly payment statement</h2></div><a class="button" href="/api/export.csv?month=${encodeURIComponent(month)}">Export month CSV</a></div><p class="table-note">On-screen totals follow the selected filters. CSV includes the complete authorized month.</p><div class="table-scroll"><table><thead><tr><th>Visit / FSR</th><th>Branch</th><th>Coverage</th><th>Status</th><th>Eligibility</th><th>Payable</th></tr></thead><tbody>${rows.map(visit=>`<tr><td>${esc(visit.id)}<small>${esc(visit.fsr?.fsrNumber??'No FSR submitted')}</small></td><td>${esc(visit.branchCode)}</td><td>${badge(visit.warranty)}</td><td>${badge(visit.status)}</td><td>${eligible(visit)?'Eligible':visit.warranty==='Warranty'?'Warranty · zero charge':'Awaiting eligibility'}</td><td><b>${money(eligible(visit)?visit.rate:0)}</b></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No visits match these filters.</td></tr>'}</tbody></table></div></div>`;
 if(tab==='audit'){
  const auditUser=user.id;
  $('#page').innerHTML='<div class="panel"><div class="panel-heading"><div><span class="eyebrow">TRACEABILITY</span><h2>Recorded actions</h2></div></div><div id="audit-list" role="status">Loading recorded actions…</div></div>';
  api('audit').then(items=>{if(tab!=='audit'||user.id!==auditUser)return;$('#audit-list').innerHTML=items.length?items.map(action=>`<div class="audit-row"><span class="audit-symbol">${icon('audit')}</span><div><b>${esc(action.action.replaceAll('.',' · '))}</b><span>${esc(action.entity)}</span><small>${esc(users.find(account=>account.id===action.actor)?.name??action.actor)} · ${esc(dateTime(action.at))}</small>${action.detail.reason?`<p>${esc(action.detail.reason)}</p>`:''}</div></div>`).join(''):'<div class="empty">No actions yet. Submit an FSR to begin the audit history.</div>';}).catch(error=>notify(error.message));
 }
 document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.tab;render();if(tab==='inventory')loadInventory();});
 $('#user').onchange=async event=>{try{detailVersion++;refreshVersion++;inventoryVersion++;$('#detail').close();$('#inventory-detail').close();user=await api('session',{userId:event.target.value});tab='overview';search='';region='';warranty='';status='';selectedMapBranch=null;inventoryData=null;inventoryLoading=false;inventoryError='';inventoryUpdatedAt=null;inventorySearch='';inventoryCategory='';inventoryItem='';inventoryType='';await refresh();}catch(error){notify(error.message);}};
 for(const key of ['month','region','warranty','status'])$('#'+key)?.addEventListener('change',event=>{({month:value=>month=value,region:value=>region=value,warranty:value=>warranty=value,status:value=>status=value})[key](event.target.value);render();});
 $('#search')?.addEventListener('change',event=>{search=event.target.value;render();});
 $('#clear-filters')?.addEventListener('click',()=>{search='';region='';warranty='';status='';render();});
 $('#refresh-data')?.addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await refresh();}catch(error){notify(error.message);if($('#refresh-data'))$('#refresh-data').disabled=false;}});
 $('#view-all')?.addEventListener('click',()=>{tab='visits';render();});
 document.querySelectorAll('[data-visit]').forEach(button=>button.onclick=()=>detail(button.dataset.visit));
}
function table(rows){return `<div class="table-scroll"><table><thead><tr><th>Branch / Genset</th><th>Region</th><th>Due date</th><th>Coverage</th><th>Visit status</th><th></th></tr></thead><tbody>${rows.length?rows.map(visit=>`<tr><td><b>${esc(visit.branchName)}</b><small>${esc(visit.branchCode)} · ${esc(visit.assetId)}</small></td><td>${esc(visit.region)}</td><td>${esc(visit.dueDate)}${visit.status==='scheduled'&&visit.dueDate<new Date().toISOString().slice(0,10)?'<small class="danger">Overdue</small>':''}</td><td>${badge(visit.warranty)}</td><td>${badge(visit.status)}</td><td><button class="text-button" data-visit="${esc(visit.id)}">${user.role==='technician'&&['scheduled','unacknowledged'].includes(visit.status)?'Complete FSR':'View record'} ${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No visits match these filters. Adjust or reset the filters above.</td></tr>'}</tbody></table></div>`;}
const safePhoto=value=>typeof value==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value)?value:null;
const reportValue=value=>value===undefined||value===null||value===''?'—':String(value);
function reportSections(fsr){
 const groups=[...new Set(fields.map(field=>field.group))];
 return groups.map((group,index)=>`<details class="report-section" id="report-section-${index}" open><summary><span class="section-number">${String(index+1).padStart(2,'0')}</span>${esc(group)}<small>${fields.filter(field=>field.group===group).length} fields</small></summary><div class="record-grid">${fields.filter(field=>field.group===group).map(field=>{
  const photo=field.type==='attachment'?safePhoto(fsr[field.key]):null;
  return `<div class="record-field ${field.type==='attachment'?'record-photo':''}"><small>${esc(field.label)}</small>${field.type==='attachment'?(photo?`<img class="evidence" alt="${esc(field.label)} submitted by the technician" src="${esc(photo)}">`:'<span class="missing-evidence">No photograph recorded</span>'):`<b>${esc(reportValue(fsr[field.key]))}</b>`}</div>`;
 }).join('')}</div></details>`).join('');
}
function reportMaterialUsage(fsr){
 const recorded=Array.isArray(fsr.inventoryUsage),usage=recorded?fsr.inventoryUsage:[];
 return `<details class="report-section report-materials" id="report-materials" open><summary><span class="section-number">${icon('inventory')}</span>Tracked parts & materials<small>${recorded?usage.length+' items':'Not recorded'}</small></summary>${usage.length?`<div class="table-scroll"><table data-inventory-usage><thead><tr><th>Material / SKU</th><th>Quantity used</th><th>Unit</th></tr></thead><tbody>${usage.map(item=>`<tr><td><b>${esc(item.name??item.sku??item.itemId)}</b><small>${esc(item.sku??'')}</small></td><td>${quantity(item.quantity)}</td><td>${esc(item.unit??'—')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="report-materials-empty">${recorded?'No tracked material recorded for this submission.':'Structured material usage was not recorded in this earlier report.'}</p>`}</details>`;
}
function reportActivity(report){
 const labels={'visit.started':'Visit started','fsr.submitted':'Technician submitted an FSR','fsr.acknowledged':'Client acknowledged the report','fsr.unacknowledged':'Client requested a correction'};
 const activity=report.activity??[];
 if(!activity.length)return '';
 return `<section class="report-activity"><div class="panel-heading"><div><span class="eyebrow">SERVICE TIMELINE</span><h3>Visit and client decisions</h3></div></div>${activity.map(action=>`<div class="audit-row"><span class="audit-symbol">${icon(action.action.includes('acknowledged')?'shield':'audit')}</span><div><b>${esc(labels[action.action]??action.action.replaceAll('.',' · '))}</b><small>${esc(users.find(account=>account.id===action.actor)?.name??action.actor)} · ${esc(dateTime(action.at))}</small>${action.detail?.reason?`<p>${esc(action.detail.reason)}</p>`:''}</div></div>`).join('')}</section>`;
}
function reportMarkup(report,revisionIndex){
 const {visit,asset,technician,history}=report,selected=revisionIndex===null?null:history[revisionIndex],fsr=selected?.fsr??visit.fsr;
 const isLatest=!selected||revisionIndex===history.length-1,number=selected?revisionIndex+1:history.length||1;
 const clientName=fsr.client??report.client?.name??'Not recorded',technicianName=fsr.technicianName??technician?.name??fsr.technicianId??visit.technicianId,technicianEmployeeId=fsr.technicianEmployeeId??technician?.employeeId??fsr.technicianId??'Not recorded';
 return `<div class="report-title"><div class="report-company"><span class="brand-icon">${icon('bolt')}</span><div><strong>${esc(fsr.company??report.company?.name??COMPANY)}</strong><small>FIELD SERVICE REPORT · ${esc(clientName)}</small></div></div><div class="report-reference"><span>FSR reference</span><b>${esc(fsr.fsrNumber)}</b></div></div>
 <div class="report-branch-heading"><div><span class="eyebrow">${esc(clientName)} BRANCH ${esc(visit.branchCode)}</span><h2>${esc(visit.branchName)}</h2><p>${esc(fsr.siteAddress??asset?.siteAddress??'Site address not recorded')}</p></div>${badge(isLatest?visit.status:'revision '+number)}</div>
 <div class="report-toolbar"><span>${isLatest?'Latest submitted report':'Historical report · revision '+number} <small>· ${fields.length} FSR fields</small></span><div><label class="sr-only" for="report-jump">Jump to report section</label><select id="report-jump"><option value="">Jump to a section</option>${[...new Set(fields.map(field=>field.group))].map((group,index)=>`<option value="report-section-${index}">${esc(group)}</option>`).join('')}<option value="report-materials">Tracked parts & materials</option></select><button id="print-report" class="button">${icon('print')}Print report</button></div></div>
 <div class="report-metadata"><div><small>Client</small><b>${esc(clientName)}</b></div><div><small>Genset / Asset</small><b>${esc(visit.assetId)}</b></div><div><small>Technician</small><b>${esc(technicianName)}</b><span>${esc(technicianEmployeeId)}</span></div><div><small>Visit started · PKT</small><b>${esc(dateTime(fsr.visitStartedAt??visit.startedAt))}</b></div><div><small>Submitted · PKT</small><b>${esc(dateTime(fsr.submittedAt))}</b></div><div><small>Report version</small><b>Revision ${number}${isLatest?' · Latest':''}</b></div></div>
 ${!isLatest?'<div class="revision-warning">You are viewing an earlier technician submission. The client decision below applies to the latest report.</div>':''}
 ${visit.acknowledgement?`<div class="review-note"><div>${icon('shield')}<strong>Client decision on latest report</strong>${badge(visit.acknowledgement.decision)}</div><p>${esc(visit.acknowledgement.reason||'No review comments provided.')}</p><small>${esc(users.find(account=>account.id===visit.acknowledgement.userId)?.name??visit.acknowledgement.userId)} · ${esc(visit.acknowledgement.employeeId)} · ${esc(dateTime(visit.acknowledgement.at))}</small></div>`:'<div class="review-note awaiting-note">'+icon('shield')+'<span>Awaiting branch acknowledgement. This report is visible to authorized UBL and PowerVision users.</span></div>'}
 ${reportSections(fsr)}
 ${reportMaterialUsage(fsr)}
 <section class="revision-history"><div class="panel-heading"><div><span class="eyebrow">SUBMISSION HISTORY</span><h3>Report revisions</h3></div><small>Saved technician submissions</small></div>${history.length?history.map((entry,index)=>`<div class="revision-row"><span class="revision-marker">${index+1}</span><div><b>Revision ${index+1}${index===history.length-1?' · Latest submission':''}</b><small>${esc(dateTime(entry.fsr.submittedAt))} · ${esc(entry.fsr.technicianName??technician?.name??entry.fsr.technicianId??'Technician')}</small></div><button class="text-button" data-revision="${index}" ${number===index+1?'disabled':''}>${number===index+1?'Viewing':'View revision'}</button></div>`).join(''):'<p>No previous revisions recorded.</p>'}</section>
 ${reportActivity(report)}
 ${isLatest&&user.role==='branch'&&visit.status==='submitted'?'<form id="review-form" class="branch-review-form"><span class="eyebrow">BRANCH REVIEW</span><h3>Confirm the technician’s service report</h3><label>Review comments<textarea name="reason" placeholder="Describe corrections if the report cannot be acknowledged."></textarea></label><p class="review-help">A reason is required when requesting a correction.</p><p id="form-error" class="danger" role="alert"></p><div class="review-actions"><button class="button" name="decision" value="acknowledged">'+icon('check')+'Acknowledge report</button><button class="button secondary" name="decision" value="unacknowledged">Request correction</button></div></form>':''}
 <div class="report-footnote">Shared service record · ${esc(fsr.company??report.company?.name??COMPANY)} / ${esc(clientName)} · Development demo</div>`;
}
function bindReport(report){
 $('#report-jump')?.addEventListener('change',event=>{const target=document.getElementById(event.target.value);if(target){target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'});}});
 $('#print-report')?.addEventListener('click',()=>{const title=document.title,sections=[...document.querySelectorAll('#report-body details')],states=sections.map(section=>section.open);try{document.title=`${COMPANY} · ${report.visit.fsr.fsrNumber}`;sections.forEach(section=>section.open=true);window.print();}finally{document.title=title;sections.forEach((section,index)=>section.open=states[index]);}});
 document.querySelectorAll('[data-revision]').forEach(button=>button.onclick=()=>{const scroll=$('#detail').scrollTop;$('#report-body').innerHTML=reportMarkup(report,Number(button.dataset.revision));bindReport(report);$('#detail').scrollTop=Math.min(scroll,180);});
 $('#review-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api(`visits/${encodeURIComponent(report.visit.id)}/review`,{decision:button.value,reason:new FormData(event.target).get('reason')});$('#detail').close();await refresh();notify('Client decision recorded. The updated status is available to UBL and PowerVision.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}});
}
function editableMarkup(visit,asset){
 return `<p class="form-introduction">Complete each applicable field and attach all three photos (maximum 2 MB each). Use “None” for work or issues that do not apply. Reference fields are generated when you submit.</p><div class="legacy-material-note">${icon('inventory')}<div><b>Parts and materials</b><p>Use the <a href="/technician/" target="_blank" rel="noopener">technician app</a> to select or change tracked stock usage. This form keeps the existing material quantities when you resubmit.</p></div></div>${visit.fsr?reportMaterialUsage(visit.fsr):''}${visit.acknowledgement?`<div class="review-note"><b>Client requested a correction</b><p>${esc(visit.acknowledgement.reason)}</p></div>`:''}<form id="fsr-form">${[...new Set(fields.filter(field=>field.type!=='auto').map(field=>field.group))].map(group=>`<fieldset><legend>${esc(group)}</legend><div class="form-grid">${fields.filter(field=>field.group===group&&field.type!=='auto').map(field=>`<label>${esc(field.label)}${Array.isArray(field.type)?`<select name="${esc(field.key)}" required><option value="">Select…</option>${field.type.map(option=>`<option ${visit.fsr?.[field.key]===option?'selected':''}>${esc(option)}</option>`).join('')}</select>`:field.type==='attachment'?`<input name="${esc(field.key)}" type="file" accept="image/jpeg,image/png,image/webp" required>`:`<input name="${esc(field.key)}" type="${field.type==='number'?'number':'text'}" ${field.type==='number'?'min="0" step="any"':''} ${field.type==='conditional'?'':'required'} value="${esc(visit.fsr?.[field.key]??({model:asset?.model,engineSerial:asset?.engineSerial,rating:asset?.rating}[field.key]??''))}">`}</label>`).join('')}</div></fieldset>`).join('')}<p id="form-error" class="danger" role="alert"></p><button class="button" type="submit">Submit FSR for branch review</button></form>`;
}
async function detail(id){
 const version=++detailVersion,requestedUser=user.id;let report;
 try{report=await api('visits/'+encodeURIComponent(id)+'/report');}catch(error){notify(error.message);return;}
 if(version!==detailVersion||requestedUser!==user.id)return;
 const visit=report.visit,editable=user.role==='technician'&&['scheduled','unacknowledged'].includes(visit.status),dialog=$('#detail');
 dialog.className=editable?'visit-dialog':'report-dialog';
 dialog.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${editable?'TECHNICIAN SERVICE FORM':'DETAILED SERVICE RECORD'}</span><span class="modal-heading-context">${esc(visit.assetId)} · Branch ${esc(visit.branchCode)}</span></div><button id="close" class="close-button" aria-label="Close service report">${icon('close')}</button></div>${editable?`<h2>${esc(visit.branchName)}</h2>${editableMarkup(visit,report.asset)}`:visit.fsr?`<div id="report-body">${reportMarkup(report,null)}</div>`:`<div class="unsubmitted-record"><div class="empty-icon">${icon('reports')}</div><h2>${esc(visit.branchName)}</h2><p>No field service report has been submitted for this visit.</p><div class="report-metadata"><div><small>Assigned technician</small><b>${esc(report.technician?.name??visit.technicianId)}</b></div><div><small>Scheduled date</small><b>${esc(visit.dueDate)}</b></div><div><small>Genset</small><b>${esc(visit.assetId)}</b></div><div><small>Status</small>${badge(visit.status)}</div></div><a class="button" href="/technician/" target="_blank" rel="noopener">Open technician app ${icon('external')}</a></div>`}`;
 if(!dialog.open)dialog.showModal();$('#close').onclick=()=>{detailVersion++;dialog.close();};
 if(visit.fsr&&!editable)bindReport(report);
 $('#fsr-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));if(Array.isArray(visit.fsr?.inventoryUsage))values.inventoryUsage=visit.fsr.inventoryUsage.map(item=>({itemId:item.itemId,quantity:item.quantity}));for(const field of fields.filter(field=>field.type==='attachment')){const file=values[field.key];if(file.size>2*1024*1024)throw new Error('Each image must be at most 2 MB');values[field.key]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Cannot read image'));reader.readAsDataURL(file);});}await api(`visits/${encodeURIComponent(id)}/submit`,values);dialog.close();await refresh();notify('FSR submitted. Authorized UBL and PowerVision users can now view the complete report.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}});
}
async function boot(){try{users=await api('demo-users');try{user=await api('me');}catch{user=await api('session',{userId:'ho-demo'});}mapConfiguration=await api('map-config');await refresh();}catch(error){$('#app').innerHTML=`<div class="startup-error"><h1>Unable to load your workspace</h1><p>${esc(error.message)}</p><button class="button" id="retry-startup">Try again</button></div>`;$('#retry-startup').onclick=boot;}}
boot();
setInterval(()=>{if(user&&tab==='overview'&&!refreshing&&!$('#detail').open&&document.visibilityState==='visible'&&!document.activeElement?.matches('input,select,textarea'))refresh({background:true}).catch(()=>{const label=document.querySelector('.updated-at');if(label)label.textContent='Connection lost · trying again';});},15000);
